-- Reference snapshot for the support schema already applied to Molan Business project rcubnewrfieqhwcnvrzs.
-- Do not blindly rerun on an existing database. Use tracked migrations for future changes.
create extension if not exists pgcrypto;
create table if not exists public.support_tickets (
 id uuid primary key default gen_random_uuid(),
 ticket_number bigint generated by default as identity unique,
 customer_user_id uuid not null references auth.users(id) on delete cascade,
 customer_name text not null default 'Customer',
 customer_email text not null default '',
 company_name text not null default 'Molan Business',
 subject text not null check(char_length(trim(subject)) between 3 and 180),
 initial_message text not null check(char_length(trim(initial_message)) between 1 and 12000),
 category text not null default 'general' check(category in ('general','complaint','technical','billing','account','suggestion','other')),
 priority text not null default 'normal' check(priority in ('low','normal','high','urgent')),
 status text not null default 'new' check(status in ('new','open','in_progress','awaiting_customer','escalated','resolved','closed')),
 assigned_staff_id uuid, created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(), resolved_at timestamptz
);
create table if not exists public.support_messages (
 id uuid primary key default gen_random_uuid(),
 ticket_id uuid not null references public.support_tickets(id) on delete cascade,
 sender_user_id uuid, sender_role text not null check(sender_role in ('customer','support')),
 sender_name text not null default 'Customer',
 body text not null check(char_length(trim(body)) between 1 and 12000),
 created_at timestamptz not null default now(), customer_read_at timestamptz, staff_read_at timestamptz
);
create index if not exists support_tickets_customer_updated_idx on public.support_tickets(customer_user_id,updated_at desc);
create index if not exists support_tickets_status_updated_idx on public.support_tickets(status,updated_at desc);
create index if not exists support_messages_ticket_created_idx on public.support_messages(ticket_id,created_at asc);
create index if not exists support_messages_customer_unread_idx on public.support_messages(ticket_id,sender_role,customer_read_at) where sender_role='support' and customer_read_at is null;
create or replace function public.set_support_ticket_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end; $$;
drop trigger if exists support_tickets_set_updated_at on public.support_tickets;
create trigger support_tickets_set_updated_at before update on public.support_tickets for each row execute function public.set_support_ticket_updated_at();
create or replace function public.bump_support_ticket_from_message() returns trigger language plpgsql security definer set search_path='' as $$ begin update public.support_tickets set updated_at=now() where id=new.ticket_id; return new; end; $$;
revoke execute on function public.bump_support_ticket_from_message() from public,anon,authenticated;
drop trigger if exists support_messages_bump_ticket on public.support_messages;
create trigger support_messages_bump_ticket after insert on public.support_messages for each row execute function public.bump_support_ticket_from_message();
alter table public.support_tickets enable row level security;
alter table public.support_messages enable row level security;
revoke all on public.support_tickets from anon,authenticated;
revoke all on public.support_messages from anon,authenticated;
grant select on public.support_tickets to authenticated;
grant insert(customer_user_id,customer_name,customer_email,company_name,subject,initial_message,category,priority) on public.support_tickets to authenticated;
grant select on public.support_messages to authenticated;
grant insert(ticket_id,sender_user_id,sender_role,sender_name,body) on public.support_messages to authenticated;
grant update(customer_read_at) on public.support_messages to authenticated;
grant usage,select on sequence public.support_tickets_ticket_number_seq to authenticated;
drop policy if exists "Customers read their own support tickets" on public.support_tickets;
create policy "Customers read their own support tickets" on public.support_tickets for select to authenticated using(customer_user_id=(select auth.uid()));
drop policy if exists "Customers create their own support tickets" on public.support_tickets;
create policy "Customers create their own support tickets" on public.support_tickets for insert to authenticated with check(customer_user_id=(select auth.uid()) and status='new' and assigned_staff_id is null);
drop policy if exists "Customers read messages in their own tickets" on public.support_messages;
create policy "Customers read messages in their own tickets" on public.support_messages for select to authenticated using(exists(select 1 from public.support_tickets t where t.id=support_messages.ticket_id and t.customer_user_id=(select auth.uid())));
drop policy if exists "Customers send messages in their own tickets" on public.support_messages;
create policy "Customers send messages in their own tickets" on public.support_messages for insert to authenticated with check(sender_role='customer' and sender_user_id=(select auth.uid()) and exists(select 1 from public.support_tickets t where t.id=support_messages.ticket_id and t.customer_user_id=(select auth.uid()) and t.status not in ('resolved','closed')));
drop policy if exists "Customers mark support replies as read" on public.support_messages;
create policy "Customers mark support replies as read" on public.support_messages for update to authenticated using(sender_role='support' and exists(select 1 from public.support_tickets t where t.id=support_messages.ticket_id and t.customer_user_id=(select auth.uid()))) with check(sender_role='support' and exists(select 1 from public.support_tickets t where t.id=support_messages.ticket_id and t.customer_user_id=(select auth.uid())));
